package io.github.oustery.opencodephone.core.linuxenv

import java.io.File

/**
 * Rebuilds the guest CA trust store.
 *
 * The toolset ships the `ca-certificates` package's certificate files
 * (`usr/share/ca-certificates/**/*.crt`), but the combined bundle
 * `/etc/ssl/certs/ca-certificates.crt` is generated by the package's
 * post-install script (`update-ca-certificates`) — and bootstrap extracts
 * packages app-side without running guest scripts (ADR-008). Git and curl
 * then find no CA store and every HTTPS operation fails with
 * `Problem with the SSL CA cert (path? access rights?)`.
 *
 * The bundle is a plain concatenation of the packaged PEM certificates, so
 * the app can rebuild it itself — a pure file write, no guest process.
 */
object SslTrust {

    /** Path inside the rootfs where Debian tooling looks for the CA bundle. */
    const val BUNDLE_PATH: String = "/etc/ssl/certs/ca-certificates.crt"

    /**
     * Belt and suspenders for every guest process: point git/libcurl and
     * OpenSSL clients at the bundle explicitly, even when a build compiled a
     * different default path. Written into the environment alongside the
     * bundle itself.
     */
    val guestBundleEnv: Map<String, String> = mapOf(
        "GIT_SSL_CAINFO" to BUNDLE_PATH,
        "SSL_CERT_FILE" to BUNDLE_PATH,
    )

    fun bundleFile(rootfsDir: File): File = File(rootfsDir, BUNDLE_PATH.removePrefix("/"))

    /**
     * Concatenate every packaged certificate into the bundle. Matches
     * `update-ca-certificates` sources: the package store
     * (`usr/share/ca-certificates`) plus the administrator store
     * (`usr/local/share/ca-certificates`). Returns the number of
     * certificates written, or null when the rootfs carries none at all
     * (a toolset without `ca-certificates`).
     */
    fun rebuild(rootfsDir: File): Int? {
        val sources = listOf("usr/share/ca-certificates", "usr/local/share/ca-certificates")
            .flatMap { dir -> File(rootfsDir, dir).takeIf { it.isDirectory }?.walkTopDown().orEmpty().toList() }
            .filter { it.isFile && it.extension == "crt" }
            .sortedBy { it.absolutePath }
        if (sources.isEmpty()) return null
        val target = bundleFile(rootfsDir)
        target.parentFile.mkdirs()
        val tmp = File(target.parentFile, target.name + ".tmp")
        var written = 0
        tmp.outputStream().buffered().use { out ->
            for (cert in sources) {
                val pem = cert.readText().trim()
                if (!pem.contains("BEGIN CERTIFICATE")) continue
                out.write((pem + "\n").toByteArray(Charsets.UTF_8))
                written++
            }
        }
        check(tmp.renameTo(target)) { "Cannot write CA bundle ${target.absolutePath}" }
        return written
    }

    /**
     * Cheap idempotent repair used at app start and before network git
     * operations: rewrites the bundle only when it is missing or empty.
     */
    fun ensure(rootfsDir: File): Boolean {
        val bundle = bundleFile(rootfsDir)
        if (bundle.isFile && bundle.length() > 0) return true
        return rebuild(rootfsDir) != null
    }
}
